import json,socket,concurrent.futures,subprocess,datetime,urllib.request
ports=[17448,17410,17447]
def tcp(p):
 try:
  s=socket.create_connection(('127.0.0.1',p),1.5);s.close();return 'CONNECTED'
 except Exception as e:return type(e).__name__
def http(args):
 name,url=args
 try:
  with urllib.request.urlopen(url,timeout=2.5) as r:
   body=r.read(32768)
   return {'name':name,'httpStatus':r.status,'bodyBytesFirst32k':len(body)}
 except Exception as e:return {'name':name,'error':type(e).__name__}
with concurrent.futures.ThreadPoolExecutor(max_workers=8) as pool:
 connects=dict(zip(ports,pool.map(tcp,ports)))
 links=[('health','http://127.0.0.1:17448/api/health'),('operator','http://127.0.0.1:17448/api/operator-lifecycle'),('chrome','http://127.0.0.1:17410/json/version'),('targets','http://127.0.0.1:17410/json/list')]
 tests=list(pool.map(http,links))
